const atomPaint={H:'#e5f7ff',O:'#f26d6d',C:'#657f9b',N:'#64aaf7',Na:'#a5a1e8',Cl:'#8cdb80',Fe:'#e6b480'};
function drawReaction(){if(rc.getBoundingClientRect().width<2){requestAnimationFrame(drawReaction);return;}let r=rc.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(rc.width!==Math.round(r.width*d)||rc.height!==Math.round(r.height*d)){rc.width=Math.max(1,Math.round(r.width*d));rc.height=Math.max(1,Math.round(r.height*d))}rx.setTransform(d,0,0,d,0,0);rx.clearRect(0,0,r.width,r.height);let data=reactionData[reactionIndex],t=reactionProgress,groups=t<.5?data.react:data.out;let fade=Math.min(1,Math.abs(t-.5)*6+.12),W=r.width,H=r.height;rx.globalAlpha=fade;groups.forEach((group,i)=>{let cx=(i+1)*W/(groups.length+1),cy=H/2+Math.sin(i*2.1)*28,spread=Math.min(28,W/(groups.length*3+2));group.forEach((sym,j)=>{let ang=j*2.39996+(t<.5?t*1.5:-t),rad=j===0?0:spread*(.65+.3*Math.sqrt(j)),x=cx+Math.cos(ang)*rad,y=cy+Math.sin(ang)*rad,gr=rx.createRadialGradient(x-5,y-5,1,x,y,17);gr.addColorStop(0,'#ffffff');gr.addColorStop(.4,atomPaint[sym]||'#b4c8da');gr.addColorStop(1,'#1b3b53');rx.fillStyle=gr;rx.beginPath();rx.arc(x,y,17,0,Math.PI*2);rx.fill();rx.fillStyle='#071522';rx.textAlign='center';rx.textBaseline='middle';rx.font='bold 12px system-ui';rx.fillText(sym,x,y)})});rx.globalAlpha=1;rx.fillStyle='#9ec7d7';rx.font='12px system-ui';rx.textAlign='center';rx.fillText(bilingual('Reagensek','Edukte'),W*.2,H-17);rx.fillText(bilingual('Termékek','Produkte'),W*.8,H-17);rx.fillStyle='#63d9f5';rx.fillRect(12,H-8,(W-24)*t,3);if(reactionRunning){let now=performance.now();reactionProgress=Math.min(1,reactionProgress+Math.min(.05,(now-reactionLast)/4500));if(reactionProgress>=1){reactionRunning=false;$('reactionPlay').textContent='▶'}}reactionLast=performance.now();requestAnimationFrame(drawReaction)}
function countSymbols(groups){let c={};groups.flat().forEach(x=>c[x]=(c[x]||0)+1);return Object.entries(c).sort().map(([x,n])=>x+': '+n).join(' · ')}
function renderReactionText(){let x=reactionData[reactionIndex];$('reactionEquation').textContent=x.eq;$('reactionDescription').textContent=x.desc[lang==='hu'?0:1];$('reactionBalance').textContent=bilingual('Atomok a reakció előtt és után: ','Atome vor und nach der Reaktion: ')+countSymbols(x.react)+' = '+countSymbols(x.out)+' ✓'}
