function centerPreset(preset){let p=presetData[preset],cv=$('molCanvas');if(!p||!cv)return;const box=cv.getBoundingClientRect(),w=box.width,h=box.height;if(w<100||h<100)return;
$('presets').value=preset;$('presets').dispatchEvent(new Event('change'));
let xs=molAtoms.map(a=>a.x),ys=molAtoms.map(a=>a.y);let minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);let sx=(w-80)/Math.max(1,maxX-minX),sy=(h-80)/Math.max(1,maxY-minY),scale=Math.min(1,sx,sy);let midX=(minX+maxX)/2,midY=(minY+maxY)/2;
for(const a of molAtoms){a.x=w/2+(a.x-midX)*scale;a.y=h/2+(a.y-midY)*scale}updateMolStatus()}
