// Beta 0.7 — main-group teaching model. This is NOT an ab-initio bond-energy calculation.
const chemValence={H:1,He:2,Li:1,Be:2,B:3,C:4,N:5,O:6,F:7,Ne:8,Na:1,Mg:2,Al:3,Si:4,P:5,S:6,Cl:7,Ar:8,K:1,Ca:2,Br:7,I:7};
const typicalBonds={H:1,C:4,N:3,O:2,F:1,Cl:1,Br:1,I:1,P:3,S:2};
const enValues={H:2.20,C:2.55,N:3.04,O:3.44,F:3.98,Cl:3.16,Br:2.96,I:2.66,P:2.19,S:2.58,Si:1.90,B:2.04};
function scienceT(hu,de){return lang==='hu'?hu:de}
function scienceHtml(){
 if(currentMaterialModel&&currentMaterialModel.kind!=='molecule'){ $('bondScience').innerHTML='<div class="science-result">'+scienceT('Ez kristály- vagy láncrészlet. Az oktett- és vegyértékellenőrzés önálló molekulákra készült, ezért itt nem adunk félrevezető stabilitási eredményt.','Dies ist ein Kristall- oder Kettenfragment. Die Oktett- und Valenzprüfung ist für einzelne Moleküle gedacht; deshalb wird hier keine irreführende Stabilitätsbewertung angezeigt.')+'</div>';return }
 if(!molAtoms.length){$('bondScience').innerHTML='<div class="science-result">'+scienceT('Válassz egy példamolekulát, vagy helyezz el atomokat. A program megvizsgálja a vegyértékelektronokat és a kötések számát.','Wähle ein Beispielmolekül oder platziere Atome. Das Programm untersucht Valenzelektronen und Bindungszahlen.')+'</div>';return}
 let total=molAtoms.reduce((n,a)=>n+(chemValence[a.s]??0),0),shared=molBonds.reduce((n,b)=>n+2*b.order,0);
 let html='<div class="science-grid">';
 for(const a of molAtoms.slice(0,18)){
  let e=elements.find(e=>e.s===a.s),v=chemValence[a.s],used=molBonds.filter(b=>b.a===a.id||b.b===a.id).reduce((n,b)=>n+b.order,0),target=a.s==='H'?2:8,nonbond=v===undefined?null:v-used;
  html+='<div class="science-card"><strong>'+a.s+' · '+(e?e[lang]:a.s)+'</strong>';
  if(v===undefined){html+='<p>'+scienceT('Összetett vegyérték: itt nincs egyszerű oktettmodell.','Komplexe Valenz: kein einfaches Oktettmodell.')+'</p>'}
  else {html+='<p>'+scienceT('Vegyértékelektronok: ','Valenzelektronen: ')+v+' · '+scienceT('Kötésrendösszeg: ','Bindungsordnungssumme: ')+used+'</p><div class="science-orbit">';for(let i=0;i<8;i++)html+='<span class="'+(i<v?'science-dot':'science-empty')+'"></span>';html+='</div>';
   let electronCount=2*used+Math.max(0,nonbond);let octet=(electronCount===target),over=(electronCount>target);
   html+='<p>'+scienceT('Kötésben részt vevő elektronok az atom körül: ','Bindungselektronen am Atom: ')+(2*used)+'<br>'+scienceT('Nemkötő elektronok (becslés): ','Nichtbindende Elektronen (Schätzung): ')+Math.max(0,nonbond)+'<br>'+scienceT('Oktett/duett ellenőrzés: ','Oktett/Duett-Prüfung: ')+'<b class="'+(octet?'balance-good':over?'balance-bad':'')+'">'+(octet?'✓ '+scienceT('teljes','erfüllt'):over?'! '+scienceT('túllépés','überschritten'):scienceT('nem teljes','unvollständig'))+'</b></p>';
  }html+='</div>'}
 html+='</div>';
 let unknown=molAtoms.some(a=>chemValence[a.s]===undefined),neutral=molAtoms.every(a=>{let v=chemValence[a.s],u=molBonds.filter(b=>b.a===a.id||b.b===a.id).reduce((n,b)=>n+b.order,0);return v!==undefined&&(a.s==='H'?u===1:typicalBonds[a.s]!==undefined?u===typicalBonds[a.s]:false)});
 html+='<div class="science-result"><strong>'+scienceT('Elektronmérleg','Elektronenbilanz')+'</strong><br>'+scienceT('Vegyértékelektronok összesen: ','Valenzelektronen insgesamt: ')+(unknown?'—':total)+'<br>'+scienceT('Közös kötő elektronpárok: ','Gemeinsame Bindungselektronenpaare: ')+molBonds.reduce((n,b)=>n+b.order,0)+' ('+shared+' e⁻)<br>'+scienceT('Szerkezeti ellenőrzés: ','Strukturprüfung: ')+(neutral?'<span class="balance-good">✓ '+scienceT('tipikus semleges kötésminta','typisches neutrales Bindungsmuster')+'</span>':'<span class="balance-bad">'+scienceT('nem teljes vagy nem ellenőrizhető; töltés/gyök is lehetséges','unvollständig oder nicht prüfbar; Ladungen/Radikale möglich')+'</span>')+'</div>';
 let polar=[];for(const b of molBonds){let a=molAtoms.find(x=>x.id===b.a),c=molAtoms.find(x=>x.id===b.b);if(a&&c&&enValues[a.s]!=null&&enValues[c.s]!=null){let delta=Math.abs(enValues[a.s]-enValues[c.s]);polar.push(a.s+'–'+c.s+': Δχ ≈ '+delta.toFixed(2)+' ('+(delta<.4?scienceT('gyengén poláris / apoláris','schwach polar / unpolar'):scienceT('poláris kovalens','polar kovalent'))+')')}}
 if(polar.length)html+='<div class="science-result"><strong>'+scienceT('Elektronegativitás és kötéspolaritás','Elektronegativität und Bindungspolarität')+'</strong><br>'+polar.slice(0,12).join('<br>')+'</div>';
 html+='<p class="science-muted">'+scienceT('A kötések azért alakulhatnak ki, mert a teljes rendszer energiája megfelelő feltételek mellett csökkenhet. Az oktettszabály és a kötésrend csak egyszerűsített ellenőrzés: nem bizonyítja a stabilitást, nem számít aktiválási energiát vagy pályaenergiákat. A kovalens kötésben a magok vonzása és az elektroneloszlás kvantummechanikai állapota együtt számít.','Bindungen können entstehen, wenn die Gesamtenergie des Systems unter geeigneten Bedingungen sinkt. Oktettregel und Bindungsordnung sind nur vereinfachte Prüfungen; sie beweisen weder Stabilität noch berechnen sie Aktivierungs- oder Orbitalenergien. Die quantenmechanische Elektronenverteilung und die Kernanziehung wirken zusammen.')+'</p>';
 $('bondScience').innerHTML=html;
}
