// Interactive stoichiometric balancing, using explicit formula compositions.
const balanceData={water:{parts:['H₂','O₂','H₂O'],side:[-1,-1,1],atoms:[{H:2},{O:2},{H:2,O:1}],solution:[2,1,2]},carbon:{parts:['C','O₂','CO₂'],side:[-1,-1,1],atoms:[{C:1},{O:2},{C:1,O:2}],solution:[1,1,1]},methane:{parts:['CH₄','O₂','CO₂','H₂O'],side:[-1,-1,1,1],atoms:[{C:1,H:4},{O:2},{C:1,O:2},{H:2,O:1}],solution:[1,2,1,2]},neutral:{parts:['HCl','NaOH','NaCl','H₂O'],side:[-1,-1,1,1],atoms:[{H:1,Cl:1},{Na:1,O:1,H:1},{Na:1,Cl:1},{H:2,O:1}],solution:[1,1,1,1]},rust:{parts:['Fe','O₂','Fe₂O₃'],side:[-1,-1,1],atoms:[{Fe:1},{O:2},{Fe:2,O:3}],solution:[4,3,2]}};
let balanceValues={};
function renderBalance(){let data=reactionData[reactionIndex],m=balanceData[data.id];if(!m)return;let k=data.id;if(!balanceValues[k])balanceValues[k]=m.parts.map(()=>1);$('balanceTitle').textContent=scienceT('Rendezd a reakcióegyenletet!','Gleiche die Reaktionsgleichung aus!');$('balanceHelp').textContent=scienceT('Írd be az együtthatókat! A táblázat élőben mutatja, hogy minden atomból ugyanannyi van-e a két oldalon.','Trage die Koeffizienten ein! Die Tabelle zeigt live, ob auf beiden Seiten gleich viele Atome vorhanden sind.');$('balanceSolve').textContent=scienceT('Ellenőrzés','Prüfen');$('balanceReveal').textContent=scienceT('Megoldás mutatása','Lösung zeigen');let root=$('balanceInputs');root.replaceChildren();m.parts.forEach((part,i)=>{if(i){let sep=document.createElement('span');sep.textContent=m.side[i]!==m.side[i-1]?' → ':' + ';root.appendChild(sep)}let span=document.createElement('label');span.className='balance-term';let inp=document.createElement('input');inp.type='number';inp.min='1';inp.max='99';inp.step='1';inp.value=balanceValues[k][i];inp.setAttribute('aria-label',part+' '+scienceT('együttható','Koeffizient'));inp.oninput=()=>{balanceValues[k][i]=Number(inp.value);updateBalance()};let name=document.createElement('strong');name.textContent=part;span.append(inp,name);root.appendChild(span)});updateBalance()}
function getBalance(){let data=reactionData[reactionIndex],m=balanceData[data.id],values=balanceValues[data.id],symbols=[...new Set(m.atoms.flatMap(x=>Object.keys(x)))].sort(),valid=values.every(x=>Number.isInteger(x)&&x>=1&&x<=99);let rows=symbols.map(sym=>{let l=0,r=0;m.atoms.forEach((atom,i)=>{if(m.side[i]<0)l+=(atom[sym]||0)*(values[i]||0);else r+=(atom[sym]||0)*(values[i]||0)});return{sym,l,r,ok:l===r}});return{rows,valid,balanced:valid&&rows.every(x=>x.ok)}}
function updateBalance(){let x=getBalance(),head=scienceT('Atom','Atom')+' | '+scienceT('Bal oldal','Links')+' | '+scienceT('Jobb oldal','Rechts');$('balanceAnalysis').innerHTML='<table class="balance-table"><thead><tr>'+head.split(' | ').map(s=>'<th>'+s+'</th>').join('')+'</tr></thead><tbody>'+x.rows.map(r=>'<tr class="'+(r.ok?'balance-good':'balance-bad')+'"><td>'+r.sym+'</td><td>'+r.l+'</td><td>'+r.r+'</td></tr>').join('')+'</tbody></table>';$('balanceFeedback').textContent=x.balanced?scienceT('✓ Az atomok száma mindkét oldalon megegyezik. Az egyenlet rendezett (az együtthatók még egyszerűsíthetők).','✓ Die Atomzahlen stimmen auf beiden Seiten überein. Die Gleichung ist ausgeglichen (Koeffizienten eventuell kürzbar).'):scienceT('A piros soroknál még nem egyezik az atomok száma.','In den roten Zeilen stimmen die Atomzahlen noch nicht überein.')}
$('balanceSolve').onclick=()=>{updateBalance()};$('balanceReveal').onclick=()=>{let m=balanceData[reactionData[reactionIndex].id];balanceValues[reactionData[reactionIndex].id]=m.solution.slice();renderBalance()};
